{
  "claims": [
    {
      "claim_text": "Redis replication is non-blocking on the master side.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states this directly.",
      "citations": [
        {
          "index": 0,
          "quote": "Redis replication is non-blocking on the master side."
        }
      ]
    },
    {
      "claim_text": "After the initial sync a replica keeps serving queries from the old dataset while it loads the new one.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says that after the initial sync, the old dataset must be deleted and the new one loaded, and the replica blocks incoming connections during that window. Serving queries from the old dataset applies during initial synchronization, not after it.",
      "citations": [
        {
          "index": 0,
          "quote": "However, after the initial sync, the old dataset must be deleted and the new one must be loaded. The replica will block incoming connections during this brief window"
        }
      ]
    },
    {
      "claim_text": "Replicas that reconnect use PSYNC.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that replicas connect to masters using PSYNC.",
      "citations": [
        {
          "index": 1,
          "quote": "When replicas connect to masters, they use the `PSYNC` command to send their old master replication ID and the offsets they processed so far."
        }
      ]
    },
    {
      "claim_text": "A full resynchronization only happens when the replica's replication ID is unknown to the master.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says a full resynchronization also happens when there is not enough backlog in the master buffers, not only when the replication ID is unknown.",
      "citations": [
        {
          "index": 1,
          "quote": "However if there is not enough *backlog* in the master buffers, or if the replica is referring to an history (replication ID) which is no longer known, then a full resynchronization happens"
        }
      ]
    },
    {
      "claim_text": "After a failover the promoted replica keeps its replication ID.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage says the promoted replica later selects a new random replication ID; it remembers the old ID as a secondary ID, but it does not keep it as its current replication ID.",
      "citations": [
        {
          "index": 2,
          "quote": "Later it will select a new random replication ID, because a new history begins."
        },
        {
          "index": 3,
          "quote": "In case you wonder why a replica promoted to master needs to change its replication ID after a failover"
        }
      ]
    },
    {
      "claim_text": "The old master's replicas can still continue with a partial sync after a failover.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that a promoted instance can perform a partial resynchronization with the replicas of the old master.",
      "citations": [
        {
          "index": 8,
          "quote": "Since Redis 4.0, when an instance is promoted to master after a failover, it will still be able to perform a partial resynchronization with the replicas of the old master."
        }
      ]
    },
    {
      "claim_text": "Partial sync after failover has been possible since Redis 4.0.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly says this behavior is possible since Redis 4.0.",
      "citations": [
        {
          "index": 8,
          "quote": "Since Redis 4.0, when an instance is promoted to master after a failover, it will still be able to perform a partial resynchronization with the replicas of the old master."
        }
      ]
    },
    {
      "claim_text": "Diskless replication was first available in Redis 2.6.18.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage states that Redis version 2.8.18 is the first version with diskless replication support.",
      "citations": [
        {
          "index": 4,
          "quote": "Redis version 2.8.18 is the first version to have support for diskless replication."
        }
      ]
    },
    {
      "claim_text": "Diskless replication sends the RDB to replicas without using the disk as intermediate storage.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that the child process sends the RDB directly over the wire without using disk as intermediate storage.",
      "citations": [
        {
          "index": 4,
          "quote": "In this setup the child process directly sends the RDB over the wire to replicas, without using the disk as intermediate storage."
        }
      ]
    },
    {
      "claim_text": "Read-only replicas reject all write commands.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states this directly.",
      "citations": [
        {
          "index": 5,
          "quote": "Read-only replicas will reject all write commands"
        }
      ]
    },
    {
      "claim_text": "Read-only replicas are safe to expose to untrusted networks.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly says the feature is not intended to expose a replica to the internet or networks with untrusted clients, because administrative commands remain enabled.",
      "citations": [
        {
          "index": 5,
          "quote": "This does not mean that the feature is intended to expose a replica instance to the internet or more generally to a network where untrusted clients exist, because administrative commands like `DEBUG` or `CONFIG` are still enabled."
        }
      ]
    },
    {
      "claim_text": "Writes made to a writable replica are discarded when the replica and the master resync.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage says writes to a replica will be discarded if the replica and the master resync.",
      "citations": [
        {
          "index": 6,
          "quote": "While writes to a replica will be discarded if the replica and the master resync or if the replica is restarted, there is no guarantee that they will sync automatically."
        }
      ]
    },
    {
      "claim_text": "Before Redis 4.0, writable replicas could not expire keys with a TTL.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that before version 4.0, writable replicas were incapable of expiring keys with a time to live set.",
      "citations": [
        {
          "index": 7,
          "quote": "Before version 4.0, writable replicas were incapable of expiring keys with a time to live set."
        }
      ]
    },
    {
      "claim_text": "A replica restarted from its AOF file can still be partially resynchronized.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passage explicitly states that it is not possible to partially sync a replica that restarted via the AOF file.",
      "citations": [
        {
          "index": 9,
          "quote": "It is not possible to partially sync a replica that restarted via the AOF file."
        }
      ]
    }
  ]
}
